    int maxLen = 0;
    pair<int, int> dfs(TreeNode* node) {
        if (!node) return {0, 0};
        int inc = 1, dec = 1;
        if (node->left) {
            auto [lInc, lDec] = dfs(node->left);
            if (node->val == node->left->val + 1) dec = max(dec, lDec + 1);
            else if (node->val == node->left->val - 1) inc = max(inc, lInc + 1);
        }
        if (node->right) {
            auto [rInc, rDec] = dfs(node->right);
            if (node->val == node->right->val + 1) dec = max(dec, rDec + 1);
