class Solution {
    private int maxLen = 0;

    private int[] dfs(TreeNode node) {
        if (node == null) return new int[]{0, 0};
        int inc = 1, dec = 1;
        if (node.left != null) {
            int[] left = dfs(node.left);
            if (node.val == node.left.val + 1) dec = Math.max(dec, left[1] + 1);
            else if (node.val == node.left.val - 1) inc = Math.max(inc, left[0] + 1);
        }
        if (node.right != null) {
            int[] right = dfs(node.right);
            if (node.val == node.right.val + 1) dec = Math.max(dec, right[1] + 1);
            else if (node.val == node.right.val - 1) inc = Math.max(inc, right[0] + 1);
        }
        maxLen = Math.max(maxLen, inc + dec - 1);
        return new int[]{inc, dec};
    }

    public int longestConsecutive(TreeNode root) {
        maxLen = 0;
        dfs(root);
        return maxLen;
    }
}

